document.addEventListener('DOMContentLoaded',()=>{const mobileMenuToggle=document.querySelector('.mobile-menu-toggle');const mobileMenuOverlay=document.getElementById('mobileMenuOverlay');const mobileMenuClose=document.getElementById('mobileMenuClose');console.log('Mobile menu elements:',{toggle:mobileMenuToggle,overlay:mobileMenuOverlay,close:mobileMenuClose});function openMobileMenu(){console.log('Opening mobile menu');if(mobileMenuOverlay){mobileMenuOverlay.style.cssText=` display:flex!important;position:fixed!important;top:0!important;left:0!important;right:0!important;bottom:0!important;width:100vw!important;height:100vh!important;background-color:#0a0b0c!important;z-index:999999!important;flex-direction:column!important;overflow-y:auto!important;`;mobileMenuOverlay.classList.add('active');document.body.classList.add('mobile-menu-open');document.body.style.overflow='hidden';if(mobileMenuToggle){mobileMenuToggle.setAttribute('aria-expanded','true');mobileMenuToggle.classList.add('active')}}}function closeMobileMenu(){console.log('Closing mobile menu');if(mobileMenuOverlay){mobileMenuOverlay.style.cssText='';mobileMenuOverlay.classList.remove('active');document.body.classList.remove('mobile-menu-open');document.body.style.overflow='';if(mobileMenuToggle){mobileMenuToggle.setAttribute('aria-expanded','false');mobileMenuToggle.classList.remove('active')}}}if(mobileMenuToggle){mobileMenuToggle.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();console.log('Hamburger clicked');if(mobileMenuOverlay&&mobileMenuOverlay.classList.contains('active')){closeMobileMenu()}else{openMobileMenu()}})}if(mobileMenuClose){mobileMenuClose.addEventListener('click',(e)=>{e.preventDefault();closeMobileMenu()})}if(mobileMenuOverlay){const menuLinks=mobileMenuOverlay.querySelectorAll('.mobile-menu-nav a:not(.mobile-menu-view-all)');menuLinks.forEach(link=>{link.addEventListener('click',closeMobileMenu)});const dropdownToggles=mobileMenuOverlay.querySelectorAll('.mobile-menu-dropdown-toggle');dropdownToggles.forEach(toggle=>{toggle.addEventListener('click',(e)=>{e.preventDefault();const dropdown=toggle.closest('.mobile-menu-dropdown');if(dropdown){dropdown.classList.toggle('active');toggle.setAttribute('aria-expanded',dropdown.classList.contains('active'))}})})}document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&mobileMenuOverlay&&mobileMenuOverlay.classList.contains('active')){closeMobileMenu()}})});document.addEventListener('DOMContentLoaded',()=>{const navbar=document.querySelector('.navbar');if(navbar){let lastScrollY=window.scrollY;let ticking=false;window.addEventListener('scroll',()=>{if(!ticking){window.requestAnimationFrame(()=>{const currentScrollY=window.scrollY;if(currentScrollY>50){navbar.classList.add('scrolled')}else{navbar.classList.remove('scrolled');navbar.classList.remove('navbar-hidden')}if(currentScrollY>100){if(currentScrollY>lastScrollY&&currentScrollY-lastScrollY>5){navbar.classList.add('navbar-hidden')}else if(currentScrollY<lastScrollY&&lastScrollY-currentScrollY>5){navbar.classList.remove('navbar-hidden')}}lastScrollY=currentScrollY;ticking=false});ticking=true}},{passive:true})}});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){const href=this.getAttribute('href');if(href==='#'||href===''){e.preventDefault();return}const target=document.querySelector(href);if(target){e.preventDefault();const navbarHeight=navbar.offsetHeight;const targetPosition=target.getBoundingClientRect().top+window.pageYOffset-navbarHeight;window.scrollTo({top:targetPosition,behavior:'smooth'})}})});document.addEventListener('DOMContentLoaded',()=>{const megaMenuItems=document.querySelectorAll('.navbar-menu-item-with-mega');megaMenuItems.forEach(item=>{const menuLink=item.querySelector('a');const megamenu=item.querySelector('.megamenu');let closeTimeout=null;if(menuLink&&megamenu){menuLink.addEventListener('mouseenter',()=>{if(closeTimeout){clearTimeout(closeTimeout);closeTimeout=null}megamenu.style.opacity='1';megamenu.style.visibility='visible';megamenu.style.pointerEvents='all'});menuLink.addEventListener('mouseleave',()=>{closeTimeout=setTimeout(()=>{megamenu.style.opacity='0';megamenu.style.visibility='hidden';megamenu.style.pointerEvents='none';closeTimeout=null},300)});megamenu.addEventListener('mouseenter',()=>{if(closeTimeout){clearTimeout(closeTimeout);closeTimeout=null}megamenu.style.opacity='1';megamenu.style.visibility='visible';megamenu.style.pointerEvents='all'});megamenu.addEventListener('mouseleave',()=>{closeTimeout=setTimeout(()=>{megamenu.style.opacity='0';megamenu.style.visibility='hidden';megamenu.style.pointerEvents='none';closeTimeout=null},500)})}});const footerDropdowns=document.querySelectorAll('.footer-dropdown-toggle');footerDropdowns.forEach(toggle=>{toggle.addEventListener('click',()=>{const dropdown=toggle.closest('.footer-dropdown');if(dropdown){dropdown.classList.toggle('active');const isExpanded=dropdown.classList.contains('active');toggle.setAttribute('aria-expanded',isExpanded)}})})});